// What '#supabase/server' resolves to under the evals. The real module is
// generated by Nuxt and only exists inside a Nuxt build; the prompt code the
// evals run imports server utilities that import it, but an eval never talks
// to a database, so anything that reaches here is a mistake in the eval.
function notInEvals(): never {
  throw new Error('The receptionist evals do not touch a database.')
}

export const serverSupabaseServiceRole = notInEvals
export const serverSupabaseClient = notInEvals
export const serverSupabaseUser = notInEvals
